// Tray icon and window icon that reflect the blocking status.
//
// The PNGs under `icons/status/` are generated by `scripts/generate-icons.sh`.

use serde::Deserialize;
use tauri::image::Image;
use tauri::menu::{Menu, MenuItem};
use tauri::tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent};
use tauri::{AppHandle, Manager};

const TRAY_ID: &str = "status";

#[derive(Clone, Copy, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Status {
    /// Daemon not connected yet (or unreachable).
    Inactive,
    Blocked,
    /// Free Mode unblock countdown is running.
    Unblocking,
    Unblocked,
}

impl Status {
    fn icon_bytes(self) -> &'static [u8] {
        match self {
            Status::Inactive => include_bytes!("../icons/status/inactive.png"),
            Status::Blocked => include_bytes!("../icons/status/blocked.png"),
            Status::Unblocking => include_bytes!("../icons/status/unblocking.png"),
            Status::Unblocked => include_bytes!("../icons/status/unblocked.png"),
        }
    }

    fn tooltip(self) -> &'static str {
        match self {
            Status::Inactive => "Free Mind: daemon not connected",
            Status::Blocked => "Free Mind: blocking",
            Status::Unblocking => "Free Mind: unblocking…",
            Status::Unblocked => "Free Mind: not blocking",
        }
    }
}

fn show_main(app: &AppHandle) {
    if let Some(window) = app.get_webview_window("main") {
        let _ = window.unminimize();
        let _ = window.show();
        let _ = window.set_focus();
    }
}

pub fn setup(app: &AppHandle) -> tauri::Result<()> {
    let show = MenuItem::with_id(app, "show", "Show Free Mind", true, None::<&str>)?;
    let quit = MenuItem::with_id(app, "quit", "Quit", true, None::<&str>)?;
    let menu = Menu::with_items(app, &[&show, &quit])?;

    TrayIconBuilder::with_id(TRAY_ID)
        .icon(Image::from_bytes(Status::Inactive.icon_bytes())?)
        .tooltip(Status::Inactive.tooltip())
        .menu(&menu)
        .show_menu_on_left_click(false)
        .on_menu_event(|app, event| match event.id().as_ref() {
            "show" => show_main(app),
            "quit" => app.exit(0),
            _ => {}
        })
        .on_tray_icon_event(|tray, event| {
            if let TrayIconEvent::Click {
                button: MouseButton::Left,
                button_state: MouseButtonState::Up,
                ..
            } = event
            {
                show_main(tray.app_handle());
            }
        })
        .build(app)?;
    Ok(())
}

/// Swaps the tray icon and the window (taskbar) icon. macOS ignores window
/// icons, so there only the tray changes.
pub fn set_status(app: &AppHandle, status: Status) -> tauri::Result<()> {
    let icon = Image::from_bytes(status.icon_bytes())?;
    if let Some(tray) = app.tray_by_id(TRAY_ID) {
        tray.set_icon(Some(icon.clone()))?;
        tray.set_tooltip(Some(status.tooltip()))?;
    }
    if let Some(window) = app.get_webview_window("main") {
        window.set_icon(icon)?;
    }
    Ok(())
}
